### Code Snippets

```
for (
statement 1
;
statement 2
;
statement 3
) {
// code block to be executed
}

---

for (int i = 0; i < 5; i++) {
cout << i << "\n";
}

---

for (int i = 0; i <= 10; i = i + 2) {
cout << i << "\n";
}

---

int sum = 0;
for (int i = 1; i <= 5; i++) {
sum = sum + i;
}
cout << "Sum is " << sum;

---

for (int i = 5; i > 0; i--) {
cout << i << "\n";
}
```
